-- 009: CP-sheet dedup. Duplicate problems that used to appear in several topic sections were
-- collapsed to a single best-fit section. Each occurrence had its own item id, so move any saved
-- checklist progress / scratchpad code from a removed id to the kept id. On a (user,new) conflict the
-- already-kept row wins (UPDATE OR IGNORE leaves the old row, then it is deleted). Idempotent: after
-- the first run no old ids remain, so re-running matches nothing.
CREATE TEMP TABLE _remap (old TEXT PRIMARY KEY, new TEXT NOT NULL);
UPDATE OR IGNORE sheet_progress SET item_id = (SELECT new FROM _remap WHERE old = sheet_progress.item_id)
  WHERE item_id IN (SELECT old FROM _remap);
DELETE FROM sheet_progress WHERE item_id IN (SELECT old FROM _remap);
UPDATE OR IGNORE sheet_code SET item_id = (SELECT new FROM _remap WHERE old = sheet_code.item_id)
  WHERE item_id IN (SELECT old FROM _remap);
DELETE FROM sheet_code WHERE item_id IN (SELECT old FROM _remap);
DROP TABLE _remap;
